package net.barttolo.reliquias;
import com.mojang.brigadier.arguments.*;
import net.minecraft.commands.*;
import net.minecraft.commands.arguments.EntityArgument;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.event.RegisterCommandsEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import static net.minecraft.commands.Commands.*;
public final class Commands {
 private static void state(CommandSourceStack s,ServerPlayer p){s.sendSuccess(()->Component.literal("[Reliquias] "+p.getGameProfile().getName()),false);for(var t:RelicType.values()){int n=Progress.level(p,t);s.sendSuccess(()->Component.literal(t.name+": "+n+"/10 · "+t.total(n)).withStyle(t.color),false);}}
 private static net.minecraft.commands.CommandSourceStack src(com.mojang.brigadier.context.CommandContext<CommandSourceStack> c){return c.getSource();}
 private static com.mojang.brigadier.builder.RequiredArgumentBuilder<CommandSourceStack,String> type(){return argument("tipo",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(java.util.Arrays.stream(RelicType.values()).map(t->t.id),b));}
 private static RelicType selected(com.mojang.brigadier.context.CommandContext<CommandSourceStack> c)throws com.mojang.brigadier.exceptions.CommandSyntaxException{try{return RelicType.byId(StringArgumentType.getString(c,"tipo"));}catch(IllegalArgumentException e){throw new com.mojang.brigadier.exceptions.SimpleCommandExceptionType(Component.literal("Tipo de reliquia desconocido")).create();}}
 @SubscribeEvent public void register(RegisterCommandsEvent event){var root=literal("reliquias").executes(c->{state(src(c),src(c).getPlayerOrException());return 1;});root.then(literal("estado").executes(c->{state(src(c),src(c).getPlayerOrException());return 1;}).then(argument("jugador",EntityArgument.player()).requires(s->s.hasPermission(2)).executes(c->{state(src(c),EntityArgument.getPlayer(c,"jugador"));return 1;})));
 root.then(literal("dar").requires(s->s.hasPermission(2)).then(argument("jugador",EntityArgument.player()).then(type().then(argument("cantidad",IntegerArgumentType.integer(1,640)).executes(c->{var p=EntityArgument.getPlayer(c,"jugador");var t=selected(c);int quantity=IntegerArgumentType.getInteger(c,"cantidad");int capacity=0;for(int i=0;i<36;i++){var st=p.getInventory().getItem(i);if(st.isEmpty())capacity+=64;else if(st.is(Reliquias.ITEMS.get(t).get()))capacity+=64-st.getCount();}if(capacity<quantity){src(c).sendFailure(Component.literal("Inventario insuficiente; no se entregó ningún objeto."));return 0;}int left=quantity;while(left>0){int n=Math.min(left,64);p.getInventory().add(new ItemStack(Reliquias.ITEMS.get(t).get(),n));left-=n;}Progress.save(p);Reliquias.LOG.info("{} gave {} {} to {}",src(c).getTextName(),quantity,t.id,p.getUUID());src(c).sendSuccess(()->Component.literal("Reliquias entregadas: "+quantity),true);return quantity;})))));
 for(String op:new String[]{"quitar","establecer"})root.then(literal(op).requires(s->s.hasPermission(2)).then(argument("jugador",EntityArgument.player()).then(type().then(argument("niveles",IntegerArgumentType.integer(0,10)).executes(c->{var p=EntityArgument.getPlayer(c,"jugador");var t=selected(c);int n=IntegerArgumentType.getInteger(c,"niveles");Progress.set(p,t,op.equals("quitar")?Progress.level(p,t)-n:n);Reliquias.LOG.info("{} {} {} {} for {}",src(c).getTextName(),op,t.id,n,p.getUUID());state(src(c),p);return 1;})))));
 root.then(literal("reiniciar").requires(s->s.hasPermission(2)).then(argument("jugador",EntityArgument.player()).executes(c->{src(c).sendFailure(Component.literal("Para confirmar: /reliquias reiniciar "+EntityArgument.getPlayer(c,"jugador").getGameProfile().getName()+" confirmar. Se reinician mejoras; los premios reclamados se conservan."));return 0;}).then(literal("confirmar").executes(c->{var p=EntityArgument.getPlayer(c,"jugador");for(var t:RelicType.values())Progress.set(p,t,0);Reliquias.LOG.warn("{} reset relic LEVELS for {}",src(c).getTextName(),p.getUUID());state(src(c),p);return 1;}))));
 root.then(literal("recompensas").requires(s->s.hasPermission(2)).then(argument("jugador",EntityArgument.player()).executes(c->{var p=EntityArgument.getPlayer(c,"jugador");var result=Rewards.status(p);src(c).sendSuccess(()->Component.literal("Recompensas reclamadas: "+result.claimed()+" · Pendientes: "+result.pending()+" · Jefe: "+result.boss()),false);return 1;})));
 root.then(literal("recompensa").requires(s->s.hasPermission(2)).then(literal("otorgar").then(argument("jugador",EntityArgument.player()).then(argument("id_mision",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(Rewards.MISSIONS,b)).executes(c->{String id=StringArgumentType.getString(c,"id_mision");if(!Rewards.MISSIONS.contains(id)){src(c).sendFailure(Component.literal("ID de misión no válido"));return 0;}Reliquias.LOG.warn("{} administratively requests reward {} for {}",src(c).getTextName(),id,EntityArgument.getPlayer(c,"jugador").getUUID());return Rewards.missionVictory(EntityArgument.getPlayer(c,"jugador"),id)?1:0;})))).then(literal("consultar").then(argument("jugador",EntityArgument.player()).then(argument("id_mision",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(Rewards.MISSIONS,b)).executes(c->{var p=EntityArgument.getPlayer(c,"jugador");String id=StringArgumentType.getString(c,"id_mision");src(c).sendSuccess(()->Component.literal(id+": "+(Rewards.claimed(p,id)?"reclamada":"sin reclamar")),false);return 1;})))));
 event.getDispatcher().register(root);}
}
